def safe_ser(obj):
    if obj is None or isinstance(obj, (bool, int, float)):
        return obj
    if isinstance(obj, str):
        return obj[:MAX_STR] + f"...[len={len(obj)}]" if len(obj) > MAX_STR else obj
    if isinstance(obj, bytes):
        return safe_ser(repr(obj))
    if isinstance(obj, (list, tuple)):
        if len(obj) > 20:
            return [safe_ser(x) for x in obj[:20]] + [f"...[len={len(obj)}]"]
        return [safe_ser(x) for x in obj]
    if isinstance(obj, dict):
        items = list(obj.items())
        if len(items) > 20:
            r = {str(k): safe_ser(v) for k, v in items[:20]}
            r["__trunc__"] = len(obj)
            return r
        return {str(k): safe_ser(v) for k, v in items}
    if isinstance(obj, (set, frozenset)):
        lst = list(obj)[:20]
        try:
            lst = sorted(lst)
        except TypeError:
            pass
        return safe_ser(lst)
    r = repr(obj)
    return r[:MAX_STR] + "..." if len(r) > MAX_STR else r


class Tracer:
    def __init__(self, targets, source_map=None, limit=MAX_TRACE):
        self.targets = targets if isinstance(targets, set) else {targets}
        self.source_map = source_map or {}
        self.limit = limit
        self.data = []
        self.count = 0
        self._decomposer = AssertDecomposer()

    def __call__(self, frame, event, arg):
        if self.count >= self.limit:
            return None
        fname = frame.f_code.co_filename
        if fname not in self.targets:
            return self
        if event not in ("call", "line", "return", "exception"):
            return self

        lvars = {}
        for k, v in frame.f_locals.items():
            if k.startswith("__"):
                continue
            try:
                lvars[k] = safe_ser(v)
            except Exception:
                lvars[k] = "<err>"

        source_tag = "test" if fname == "<test>" else "solution"
        entry = {"line": frame.f_lineno, "event": event,
                 "func": frame.f_code.co_name, "locals": lvars,
                 "source": source_tag}
        if event == "return":
            try:
                entry["return_value"] = safe_ser(arg)
            except Exception:
                entry["return_value"] = "<err>"
        if event == "exception" and arg:
            try:
                entry["exception"] = {"type": type(arg[1]).__name__, "message": str(arg[1])}
            except Exception:
                entry["exception"] = {"type": "unknown", "message": "unknown"}

        if event == "line":
            lines = self.source_map.get(fname)
            if lines and 0 < frame.f_lineno <= len(lines):
                source_line = lines[frame.f_lineno - 1].strip()
                if source_line.startswith("assert "):
                    try:
                        result = self._decomposer.decompose(
                            source_line, frame.f_locals, frame.f_globals
                        )
                        if result:
                            entry["actual"] = safe_ser(result["actual"])
                            entry["expected"] = safe_ser(result["expected"])
                            entry["assert_match"] = result["match"]
                            entry["assert_expression"] = result["expression"]
                    except Exception:
                        pass

        self.data.append(entry)
        self.count += 1
        return self


def run():
    inp = json.loads(sys.stdin.read())
    sol_code = inp["solution"]
    test_code = inp["test_code"]
    source = inp["source"]

    result = {"verdict": False, "trace_raw": [],
              "test_results": {"passed": 0, "failed": 0, "error": None}}

    ns = {}
    try:
        exec(COMMON_IMPORTS, ns)
    except Exception:
        pass

    try:
        code_obj = compile(sol_code, "<solution>", "exec")
    except SyntaxError as e:
        result["test_results"]["error"] = f"SyntaxError: {e}"
        print(json.dumps(result))
        return

    source_map = {
        "<solution>": sol_code.splitlines(),
        "<test>": test_code.splitlines(),
    }

    tracer = Tracer({"<solution>", "<test>"}, source_map)
    try:
        sys.settrace(tracer)
        exec(code_obj, ns)
        sys.settrace(None)
    except Exception as e:
        sys.settrace(None)
        result["trace_raw"] = tracer.data
        result["test_results"]["error"] = f"{type(e).__name__}: {e}"
        print(json.dumps(result))
        return

    test_tracer = Tracer({"<solution>", "<test>"}, source_map,
                         limit=MAX_TRACE - tracer.count)

    if source == "mbpp":
        stmts = [s.strip() for s in test_code.strip().split("\n") if s.strip()]
        passed = failed = 0
        first_err = None
        for stmt in stmts:
            test_tracer.source_map["<test>"] = [stmt]
            try:
                sys.settrace(test_tracer)
                exec(compile(stmt, "<test>", "exec"), ns)
                sys.settrace(None)
                passed += 1
            except AssertionError as e:
                sys.settrace(None)
                failed += 1
                if not first_err:
                    first_err = f"AssertionError: {stmt[:200]}"
            except Exception as e:
                sys.settrace(None)
                failed += 1
                if not first_err:
                    first_err = f"{type(e).__name__}: {e}"
        result["verdict"] = failed == 0 and passed > 0
        result["test_results"] = {"passed": passed, "failed": failed, "error": first_err}
    else:
        try:
            test_obj = compile(test_code, "<test>", "exec")
            sys.settrace(test_tracer)
            exec(test_obj, ns)
            sys.settrace(None)
            result["verdict"] = True
            result["test_results"]["passed"] = 1
        except AssertionError as e:
            sys.settrace(None)
            result["test_results"]["failed"] = 1
            result["test_results"]["error"] = f"AssertionError: {e}"
        except Exception as e:
            sys.settrace(None)
            result["test_results"]["failed"] = 1
            result["test_results"]["error"] = f"{type(e).__name__}: {e}"

    result["trace_raw"] = tracer.data + test_tracer.data
    print(json.dumps(result))


if __name__ == "__main__":
    run()
